/* Generated by tools/build_assessments.py --mode local - edit assessments/*.md instead */
PNT.assessments = [{"moduleId": "m01", "questions": [{"id": "m01-q01", "type": "single", "prompt": "A PNT assessment of a regional electricity network finds that no assets move and nobody navigates. What is the most appropriate conclusion?", "explanation": "Timing is a PNT capability in its own right. Electricity infrastructure, telecommunications, finance and distributed computing can depend on synchronised time without navigating.", "options": [{"id": "a1581b", "text": "The network has no PNT dependency and can be excluded from the review."}, {"id": "8aeb41", "text": "The network may still be critically PNT-dependent because it can rely on synchronised time."}, {"id": "b42cfa", "text": "The network only depends on PNT if it uses GPS receivers for asset tracking."}, {"id": "44a849", "text": "Timing dependencies only matter for navigation systems."}], "answer": "8aeb41"}, {"id": "m01-q02", "type": "single", "prompt": "A requirement states only that \"the system shall provide position\". According to the module, what should an engineer establish next?", "explanation": "Position is not automatically latitude and longitude. The engineer needs the reference frame, dimensions, accuracy, update rate and operating environment before the requirement is meaningful.", "options": [{"id": "52ef9c", "text": "The brand of GNSS receiver to be procured."}, {"id": "c312ea", "text": "The number of constellations the receiver supports."}, {"id": "0d874e", "text": "The reference frame, dimensions, accuracy, update rate and operating environment the application needs."}, {"id": "205bac", "text": "Whether latitude and longitude are displayed in degrees or radians."}], "answer": "0d874e"}, {"id": "m01-q03", "type": "match", "prompt": "Match each PNT capability to the question it answers.", "explanation": "Positioning, navigation and timing are related but distinct capabilities with different engineering requirements.", "left": [{"id": "9899aa", "text": "Positioning"}, {"id": "6c5f84", "text": "Navigation"}, {"id": "50acc0", "text": "Timing"}], "right": [{"id": "5e73b5", "text": "Where am I, or where is something?"}, {"id": "848ebb", "text": "Where am I going, and how do I get there?"}, {"id": "c78eaf", "text": "What time is it, and how accurately must systems agree on it?"}], "answer": "50acc0=c78eaf;6c5f84=848ebb;9899aa=5e73b5"}, {"id": "m01-q04", "type": "order", "prompt": "Put the stages of the first-order PNT chain in the correct order.", "explanation": "Source → Signal/Measurement → Receiver/Sensor → PNT Solution → Application. The model helps identify where dependencies and failure modes exist.", "items": [{"id": "223ea6", "text": "Source"}, {"id": "607c46", "text": "Receiver / sensor"}, {"id": "930872", "text": "Application"}, {"id": "c8b19e", "text": "Signal / measurement"}, {"id": "cdee85", "text": "PNT solution"}], "answer": "223ea6>c8b19e>607c46>cdee85>930872"}, {"id": "m01-q05", "type": "single", "prompt": "A high-accuracy receiver is reporting as healthy, but the application's position quality has degraded. Which explanation is consistent with the PNT dependency chain?", "explanation": "Failure can occur anywhere along the dependency chain. A receiver may keep operating while its correction service or the network that delivers it is unavailable.", "options": [{"id": "fd2eb1", "text": "A healthy receiver guarantees that the whole chain is healthy."}, {"id": "e99fc9", "text": "An upstream element, such as the correction service or the communications network delivering it, may have failed."}, {"id": "37290a", "text": "The application must have a software fault because the receiver is healthy."}, {"id": "d26354", "text": "Degradation can only come from the satellites themselves."}], "answer": "e99fc9"}, {"id": "m01-q06", "type": "truefalse", "prompt": "A receiver that is multi-constellation is, by definition, also multi-frequency.", "explanation": "Multi-constellation means using more than one satellite system; multi-frequency means using more than one signal band. A receiver can be one, the other, both or neither.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m01-q07", "type": "single", "prompt": "Approximately how much range error corresponds to a timing error of one microsecond in GNSS ranging?", "explanation": "Radio signals travel at roughly 300,000 km/s, so one microsecond equates to about 300 m. One nanosecond is roughly 30 cm.", "options": [{"id": "99d132", "text": "About 30 centimetres"}, {"id": "ac8121", "text": "About 3 metres"}, {"id": "94233f", "text": "About 300 metres"}, {"id": "3e18da", "text": "About 30 kilometres"}], "answer": "94233f"}, {"id": "m01-q08", "type": "single", "prompt": "Why must a typical consumer GNSS receiver estimate its own clock bias?", "explanation": "Consumer receivers lack atomic clocks. Receiver clock bias becomes the fourth unknown alongside X, Y and Z.", "options": [{"id": "44047d", "text": "Because the satellites do not carry clocks."}, {"id": "84480c", "text": "Because it does not carry a satellite-grade atomic clock, so its clock error is solved as part of the navigation solution."}, {"id": "6685fc", "text": "Because clock bias is needed only for timing applications, not positioning."}, {"id": "453962", "text": "Because the almanac does not contain time information."}], "answer": "84480c"}, {"id": "m01-q09", "type": "match", "prompt": "Match each performance characteristic to its description.", "explanation": "PNT performance is multi-dimensional. Accuracy alone does not describe whether a system is fit for purpose.", "left": [{"id": "622432", "text": "Accuracy"}, {"id": "17376b", "text": "Precision"}, {"id": "23982a", "text": "Availability"}, {"id": "c520b5", "text": "Continuity"}, {"id": "63733a", "text": "Integrity"}], "right": [{"id": "0e67bf", "text": "Closeness of a reported value to the true value"}, {"id": "12b30e", "text": "Whether the service continues without unexpected interruption during the operation"}, {"id": "2af265", "text": "Repeatability or tight grouping of repeated measurements"}, {"id": "7746f5", "text": "Whether the required service is there when needed"}, {"id": "e829fc", "text": "The trust that can be placed in the information, including warning when it should not be used"}], "answer": "17376b=2af265;23982a=7746f5;622432=0e67bf;63733a=e829fc;c520b5=12b30e"}, {"id": "m01-q10", "type": "single", "prompt": "A set of repeated position fixes is tightly grouped but consistently 12 m from the true location. How is this best described?", "explanation": "Precision is repeatability; accuracy is closeness to truth. A result can be precise yet consistently wrong.", "options": [{"id": "ded92b", "text": "Accurate but not precise"}, {"id": "35d98f", "text": "Precise but not accurate"}, {"id": "b2211b", "text": "Both accurate and precise"}, {"id": "bf0316", "text": "High integrity"}], "answer": "35d98f"}, {"id": "m01-q11", "type": "single", "prompt": "Which failure is generally more dangerous from an integrity perspective?", "explanation": "Downstream systems and operators may continue acting on convincing but wrong information. A clear loss of service is disruptive but visible.", "options": [{"id": "1d99e3", "text": "A receiver that clearly reports no position is available."}, {"id": "ead9e0", "text": "A receiver that keeps outputting a convincing but incorrect position without warning."}, {"id": "e41e58", "text": "A receiver switched off for scheduled maintenance."}, {"id": "2436b2", "text": "A receiver with a slow start-up time."}], "answer": "ead9e0"}, {"id": "m01-q12", "type": "multi", "prompt": "A receiver uses GPS, Galileo and BeiDou. Which common-mode dependencies could still affect all three at once?", "explanation": "Constellation diversity improves visibility, but shared RF paths, equipment and local interference can defeat all constellations together. Different operators do not remove these shared dependencies.", "options": [{"id": "c78da2", "text": "A single shared antenna and cable"}, {"id": "96ad4c", "text": "A strong local RF interference source"}, {"id": "f1071f", "text": "A shared power supply or processing unit"}, {"id": "fe6910", "text": "The different national operators of each constellation"}], "answer": "96ad4c,c78da2,f1071f"}, {"id": "m01-q13", "type": "multi", "prompt": "Which of these are useful first-order dependency questions for a PNT-dependent system?", "explanation": "Engineering assessment focuses on required capability, consequences, detection time, degraded operation and evidence, not product names.", "options": [{"id": "e8d93f", "text": "What happens if PNT remains available but becomes misleading?"}, {"id": "792ec3", "text": "How quickly must degradation or erroneous information be detected?"}, {"id": "7e3c63", "text": "How long can the system continue in a degraded state?"}, {"id": "526c1b", "text": "Which receiver vendor has the best-known brand?"}], "answer": "792ec3,7e3c63,e8d93f"}, {"id": "m01-q14", "type": "truefalse", "prompt": "Redundancy, diversity and dissimilarity are synonyms; adding any of them guarantees resilience.", "explanation": "They are related but distinct. A resilient design asks whether alternative sources have genuinely different failure modes.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m01-q15", "type": "single", "prompt": "A supplier says: \"Our solution is resilient to spoofing.\" Which response best reflects how a PNT engineer should engage?", "explanation": "Good PNT conversations start with requirements, threat models and evidence rather than accepting feature claims.", "options": [{"id": "2f3bc4", "text": "Accept the claim because spoofing resilience is a listed product feature."}, {"id": "5b3b7f", "text": "Reject the claim because no system can be resilient to spoofing."}, {"id": "e99516", "text": "Ask what evidence supports it, against which threat model, under what conditions, and what the system does when the threat is detected."}, {"id": "6cea5a", "text": "Ask how many constellations the product supports."}], "answer": "e99516"}]}, {"moduleId": "m02", "questions": [{"id": "m02-q01", "type": "match", "prompt": "Match each GNSS segment to its purpose.", "explanation": "A GNSS is more than satellites: space, control and user segments interact to deliver the service.", "left": [{"id": "5ed43b", "text": "Space segment"}, {"id": "972131", "text": "Control segment"}, {"id": "13cd31", "text": "User segment"}], "right": [{"id": "d8297d", "text": "Monitors and manages the constellation and uploads orbit and clock information"}, {"id": "f9b98a", "text": "Transmits ranging signals and navigation information from orbit"}, {"id": "fdee77", "text": "Receives and processes signals to produce PNT information"}], "answer": "13cd31=fdee77;5ed43b=f9b98a;972131=d8297d"}, {"id": "m02-q02", "type": "single", "prompt": "From each useful satellite, what two things does a receiver fundamentally need?", "explanation": "The navigation message helps provide satellite position; signal timing provides the range-related measurement.", "options": [{"id": "679d01", "text": "The satellite's serial number and its launch date"}, {"id": "4d375e", "text": "An estimate of where the satellite was, and a measurement related to how far away it was"}, {"id": "7e4303", "text": "The satellite's transmit power and the receiver's own position"}, {"id": "e4aec7", "text": "The almanac and a correction service subscription"}], "answer": "4d375e"}, {"id": "m02-q03", "type": "truefalse", "prompt": "EGNOS is a separate global navigation satellite constellation that can replace Galileo.", "explanation": "EGNOS is an augmentation system. It uses monitoring infrastructure and geostationary broadcasting to provide corrections and integrity-related information for supported GNSS services.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m02-q04", "type": "single", "prompt": "Why does GNSS acquisition involve searching across frequency as well as code timing?", "explanation": "Acquisition searches across possible code timing and frequency offset. Relative motion causes Doppler shift, so the frequency must be searched too.", "options": [{"id": "e7ee59", "text": "Because each satellite changes its broadcast frequency every minute."}, {"id": "1f6f25", "text": "Because relative motion between satellite and receiver creates Doppler shift."}, {"id": "a27b18", "text": "Because the receiver clock runs at a different frequency from the almanac."}, {"id": "811a95", "text": "Because frequency search removes multipath."}], "answer": "1f6f25"}, {"id": "m02-q05", "type": "single", "prompt": "What is the difference between acquisition and tracking?", "explanation": "Acquisition finds the signal. Tracking maintains lock as conditions change so measurements and data can continue to be extracted.", "options": [{"id": "437f89", "text": "Acquisition is the initial search to find and identify a signal; tracking keeps the local code and carrier aligned so measurements continue."}, {"id": "506496", "text": "Acquisition decodes navigation data; tracking computes the position."}, {"id": "5cd352", "text": "Acquisition happens in the control segment; tracking happens in the receiver."}, {"id": "cc920c", "text": "They are two names for the same process."}], "answer": "437f89"}, {"id": "m02-q06", "type": "single", "prompt": "Why is the basic GNSS code measurement called a \"pseudorange\"?", "explanation": "Range is the geometric distance. Pseudorange is the apparent range from signal travel time, including clock offsets and propagation and equipment effects.", "options": [{"id": "8d0615", "text": "Because it is measured to a pseudo-random point near the satellite."}, {"id": "d20d75", "text": "Because it is an apparent range derived from signal timing that includes clock differences and other effects, not the exact geometric distance."}, {"id": "42b72f", "text": "Because it is only an estimate made from the almanac."}, {"id": "ab1652", "text": "Because it is always longer than the true range by exactly the speed of light."}], "answer": "d20d75"}, {"id": "m02-q07", "type": "multi", "prompt": "Which are the four unknowns solved in a conventional three-dimensional GNSS solution?", "explanation": "Three spatial coordinates plus receiver clock bias, which is why at least four suitable measurements are normally needed.", "options": [{"id": "89bb16", "text": "X position"}, {"id": "7641e1", "text": "Y position"}, {"id": "8286d3", "text": "Z position"}, {"id": "699dd6", "text": "Receiver clock bias"}, {"id": "7e5e56", "text": "Satellite transmit power"}], "answer": "699dd6,7641e1,8286d3,89bb16"}, {"id": "m02-q08", "type": "match", "prompt": "Match each type of navigation data to what it provides.", "explanation": "Ephemeris is precise and satellite-specific; the almanac is a coarse constellation directory that supports acquisition.", "left": [{"id": "170337", "text": "Ephemeris"}, {"id": "470347", "text": "Almanac"}, {"id": "d59ae9", "text": "Health / service information"}, {"id": "12f032", "text": "Satellite clock information"}], "right": [{"id": "332e5c", "text": "Indicates whether particular satellite information or signals should be used"}, {"id": "556097", "text": "Coarser orbit and status information covering the wider constellation"}, {"id": "f1ea2a", "text": "Precise orbit information for the transmitting satellite during its validity period"}, {"id": "fa947b", "text": "Allows correction for predicted satellite clock offset"}], "answer": "12f032=fa947b;170337=f1ea2a;470347=556097;d59ae9=332e5c"}, {"id": "m02-q09", "type": "single", "prompt": "A receiver knows from the almanac that a satellite is overhead but has not yet decoded that satellite's ephemeris. What is the most accurate statement?", "explanation": "Knowing a satellite exists is not enough. Turning a range into a position needs accurate satellite position at the transmission time.", "options": [{"id": "c7f9bf", "text": "It can use that satellite immediately at full accuracy."}, {"id": "e8ff1f", "text": "It knows roughly where to look, but needs sufficiently accurate orbit information before the range can support a good position."}, {"id": "6f9ddd", "text": "The almanac and ephemeris are interchangeable."}, {"id": "7a0a90", "text": "It needs the control segment to transmit its position to the satellite."}], "answer": "e8ff1f"}, {"id": "m02-q10", "type": "truefalse", "prompt": "Two systems can each produce internally accurate positions yet still disagree about where an object is.", "explanation": "Different reference frames, datums, transformations or height conventions can make accurate positions disagree numerically.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "true"}, {"id": "m02-q11", "type": "single", "prompt": "A GNSS-derived height is fed into a system that expects heights above mean sea level. What is the main engineering concern?", "explanation": "Height reference must be explicit. Interfaces should define the frame, representation, height reference and any required transformation.", "options": [{"id": "1684cd", "text": "GNSS cannot measure height at all."}, {"id": "3a8557", "text": "Ellipsoidal height from GNSS is not automatically the same as an orthometric or mean-sea-level-style height."}, {"id": "b24019", "text": "Heights are always identical whichever reference is used."}, {"id": "a39d12", "text": "The concern only applies to underwater systems."}], "answer": "3a8557"}, {"id": "m02-q12", "type": "order", "prompt": "Put these steps of producing a GNSS solution in the order described in the module.", "explanation": "The system-level flow runs from acquisition through data decoding, satellite position, measurements and solution to PVT output.", "items": [{"id": "3b5a79", "text": "Measure pseudoranges from signal timing"}, {"id": "63eea9", "text": "Solve for receiver position and clock bias"}, {"id": "7da5b9", "text": "Acquire and track signals from satellites in view"}, {"id": "b1fdde", "text": "Decode the navigation data needed for the solution"}, {"id": "d48b0b", "text": "Output Position, Velocity and Time to the application"}, {"id": "db2847", "text": "Determine satellite positions and account for satellite clock information"}], "answer": "7da5b9>b1fdde>db2847>3b5a79>63eea9>d48b0b"}, {"id": "m02-q13", "type": "single", "prompt": "Four satellites are available but are clustered in one small part of the sky. Which statement is correct?", "explanation": "Satellite count alone does not determine quality. Geometry and measurement quality also matter, developed through DOP in Module 3.", "options": [{"id": "454ab5", "text": "Four satellites always give the same quality as any other four."}, {"id": "8992d9", "text": "Geometry matters: clustered satellites give poorer geometry than well-distributed ones, even with the same count."}, {"id": "4f22bf", "text": "Clustered satellites give better accuracy because their signals are similar."}, {"id": "b614dd", "text": "The receiver cannot compute any solution with clustered satellites."}], "answer": "8992d9"}, {"id": "m02-q14", "type": "single", "prompt": "An engineer wants to understand where jamming, spoofing or antenna faults could affect a GNSS system. Which mental model does the module recommend?", "explanation": "Different threats and faults enter at different stages. Knowing the chain shows where failures can enter and how they propagate.", "options": [{"id": "15a6c1", "text": "Treat the receiver as a black box that outputs coordinates."}, {"id": "1b5845", "text": "Treat the receiver as a processing chain: antenna/RF, acquisition, tracking, data decoding, measurement formation, solution and output."}, {"id": "dcb3c0", "text": "Focus only on the navigation solution algorithm."}, {"id": "16d7b6", "text": "Focus only on the satellites in the space segment."}], "answer": "1b5845"}, {"id": "m02-q15", "type": "truefalse", "prompt": "In standard GNSS positioning, the receiver must transmit its position back to the satellites to obtain a fix.", "explanation": "Standard GNSS is passive at the user end. Satellites broadcast; the receiver listens and calculates its own solution.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}]}, {"moduleId": "m03", "questions": [{"id": "m03-q01", "type": "single", "prompt": "A receiver has seven satellites and produces a position solution. What does the existence of that solution tell you about its quality?", "explanation": "A receiver can solve successfully yet still contain significant error. Measurement errors and geometry together determine quality.", "options": [{"id": "80f118", "text": "It proves the solution is accurate to within the receiver's specification."}, {"id": "e3b795", "text": "Very little on its own: quality depends on the measurement error budget and the satellite geometry."}, {"id": "c99784", "text": "It proves the geometry is good, because at least four satellites were used."}, {"id": "ea2e43", "text": "It proves integrity, because the mathematics converged."}], "answer": "e3b795"}, {"id": "m03-q02", "type": "multi", "prompt": "Which of these contribute to the GNSS pseudorange error budget?", "explanation": "Measured pseudorange = geometric range + clock, propagation and equipment effects + multipath + noise.", "options": [{"id": "d66950", "text": "Satellite orbit error"}, {"id": "56cf40", "text": "Ionospheric delay"}, {"id": "6bdc04", "text": "Multipath and NLOS reception"}, {"id": "d26f12", "text": "Receiver and instrumental effects"}, {"id": "0293e9", "text": "The user's intended destination"}], "answer": "56cf40,6bdc04,d26f12,d66950"}, {"id": "m03-q03", "type": "single", "prompt": "Why is dual-frequency measurement particularly effective against ionospheric delay?", "explanation": "The ionosphere affects different frequencies differently. That difference provides information that single-frequency measurements cannot observe in the same way.", "options": [{"id": "05f0ef", "text": "Because the ionosphere does not affect higher frequencies at all."}, {"id": "1f20a2", "text": "Because ionospheric delay is dispersive, so comparing frequencies reveals and removes much of the first-order effect."}, {"id": "abd379", "text": "Because dual-frequency receivers use atomic clocks."}, {"id": "509806", "text": "Because the second frequency is always transmitted from a different constellation."}], "answer": "1f20a2"}, {"id": "m03-q04", "type": "truefalse", "prompt": "Dual-frequency measurement removes tropospheric delay in the same way it removes first-order ionospheric delay.", "explanation": "The troposphere is broadly non-dispersive at GNSS frequencies. Its delay is normally modelled or estimated, not cancelled by frequency comparison.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m03-q05", "type": "match", "prompt": "Match each error source to its description.", "explanation": "Ionosphere: charged and dispersive. Troposphere: neutral and modelled. Multipath and receiver effects arise near and within the user equipment.", "left": [{"id": "67606b", "text": "Ionospheric delay"}, {"id": "d86b76", "text": "Tropospheric delay"}, {"id": "16a3db", "text": "Multipath"}, {"id": "d60b0f", "text": "Receiver noise"}], "right": [{"id": "273471", "text": "Thermal noise and finite signal strength within the equipment"}, {"id": "da7d52", "text": "Neutral lower atmosphere; broadly non-dispersive, so it is modelled or estimated"}, {"id": "e6cac3", "text": "Charged upper atmosphere; dispersive, so multi-frequency combinations can mitigate it"}, {"id": "f3ae02", "text": "Reflected copies arriving alongside the direct signal and distorting timing"}], "answer": "16a3db=f3ae02;67606b=e6cac3;d60b0f=273471;d86b76=da7d52"}, {"id": "m03-q06", "type": "single", "prompt": "Why are low-elevation satellites generally more affected by atmospheric delay?", "explanation": "A low-elevation signal crosses more atmosphere, increasing and complicating both ionospheric and tropospheric effects.", "options": [{"id": "b72180", "text": "Because they transmit at lower power."}, {"id": "f1a95c", "text": "Because their signals travel through a longer effective path through the atmosphere."}, {"id": "e0a38e", "text": "Because they belong to older constellations."}, {"id": "69382f", "text": "Because the almanac is less accurate for them."}], "answer": "f1a95c"}, {"id": "m03-q07", "type": "single", "prompt": "In an urban street, the direct signal from a satellite is blocked and the receiver tracks only a reflection from a building. What is this called and what is its effect?", "explanation": "In NLOS the receiver tracks only an indirect signal, so the measured path is longer than the true geometric range.", "options": [{"id": "0417f3", "text": "Multipath; it shortens the measured range."}, {"id": "3764d1", "text": "Non-line-of-sight (NLOS) reception; the apparent path is longer than the direct range, potentially biasing the measurement significantly."}, {"id": "a8e58e", "text": "Ionospheric scintillation; it causes loss of lock."}, {"id": "22da42", "text": "Masking; it has no effect on the measurement."}], "answer": "3764d1"}, {"id": "m03-q08", "type": "single", "prompt": "A receiver designer allows reflected signals to be used in difficult environments. What trade-off does this represent?", "explanation": "Accepting lower-quality measurements can keep a solution available, but at the cost of accuracy. The right trade-off depends on the application.", "options": [{"id": "94dd53", "text": "It can improve availability by keeping more measurements, while degrading accuracy."}, {"id": "7f0116", "text": "It improves both availability and accuracy with no downside."}, {"id": "e97d6e", "text": "It reduces availability but improves integrity."}, {"id": "4148c3", "text": "It has no effect because reflected signals are ignored by the solution."}], "answer": "94dd53"}, {"id": "m03-q09", "type": "match", "prompt": "Match each measurement type to its characteristic.", "explanation": "Code measurements are unambiguous but noisy. Carrier phase is precise but initially ambiguous, which is central to RTK and PPP.", "left": [{"id": "a643ab", "text": "Code pseudorange"}, {"id": "22868f", "text": "Carrier phase"}], "right": [{"id": "46e604", "text": "Relatively noisy but unambiguous"}, {"id": "dbb034", "text": "Highly precise but contains an unknown integer number of wavelengths"}], "answer": "22868f=dbb034;a643ab=46e604"}, {"id": "m03-q10", "type": "single", "prompt": "Which statement about Dilution of Precision (DOP) is correct?", "explanation": "DOP does not create ranging error. It describes how geometry magnifies measurement uncertainty. A low DOP cannot rescue bad measurements.", "options": [{"id": "2a9522", "text": "DOP is the ranging error caused by the atmosphere."}, {"id": "032bd5", "text": "DOP is a dimensionless geometry factor that amplifies existing measurement uncertainty into solution uncertainty."}, {"id": "4411a8", "text": "A low DOP guarantees an accurate position even with corrupted measurements."}, {"id": "f53ad6", "text": "DOP only applies to timing solutions."}], "answer": "032bd5"}, {"id": "m03-q11", "type": "match", "prompt": "Match each DOP term to what it describes.", "explanation": "Each DOP term describes dilution in a different part of the navigation solution.", "left": [{"id": "c2c6a2", "text": "GDOP"}, {"id": "58e03e", "text": "PDOP"}, {"id": "cfd190", "text": "HDOP"}, {"id": "2ef717", "text": "VDOP"}, {"id": "545233", "text": "TDOP"}], "right": [{"id": "37f934", "text": "Horizontal position"}, {"id": "a26342", "text": "Position and time together"}, {"id": "ea6388", "text": "Time"}, {"id": "efda70", "text": "Three-dimensional position"}, {"id": "f6d36b", "text": "Vertical position"}], "answer": "2ef717=f6d36b;545233=ea6388;58e03e=efda70;c2c6a2=a26342;cfd190=37f934"}, {"id": "m03-q12", "type": "single", "prompt": "Why is GNSS vertical accuracy commonly worse than horizontal accuracy?", "explanation": "Satellites are not distributed below the user, so vertical geometry is inherently less favourable for most users.", "options": [{"id": "e692ba", "text": "Satellites transmit weaker signals in the vertical direction."}, {"id": "a625af", "text": "Satellites are observed above the user rather than all around, giving weaker vertical geometry, so VDOP is often larger than HDOP."}, {"id": "f725f7", "text": "Height is not part of the navigation solution."}, {"id": "b82022", "text": "Vertical errors are caused only by the troposphere."}], "answer": "a625af"}, {"id": "m03-q13", "type": "truefalse", "prompt": "Two receivers using the same constellation at the same location will always produce identical performance.", "explanation": "Antenna design, receiver architecture, algorithms, installation and the surrounding environment all affect performance.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m03-q14", "type": "multi", "prompt": "A vehicle drives from open sky into an urban canyon. Which effects can occur at the same time?", "explanation": "All three can happen together. The receiver may still output a fix, but its performance may have changed significantly.", "options": [{"id": "d08601", "text": "Measurement quality degrades through multipath and NLOS."}, {"id": "84eafe", "text": "The number of usable measurements falls."}, {"id": "f76f78", "text": "DOP worsens because the visible satellites are concentrated in a strip of sky."}, {"id": "ac637c", "text": "The ionospheric delay disappears because buildings block it."}], "answer": "84eafe,d08601,f76f78"}, {"id": "m03-q15", "type": "single", "prompt": "A supplier states \"our receiver is accurate to one metre\". Which follow-up question is most important for turning this into a verifiable assurance claim?", "explanation": "A performance number without dimension, statistics, conditions and reference truth is not yet a claim you can meaningfully verify.", "options": [{"id": "367c52", "text": "What colour is the receiver housing?"}, {"id": "396ee5", "text": "How many satellites are in each constellation?"}, {"id": "9ec12f", "text": "Is it horizontal, vertical or 3D, at what statistical confidence, under what conditions, and against what reference truth?"}, {"id": "0bc0d3", "text": "Does the receiver support a touchscreen?"}], "answer": "9ec12f"}]}, {"moduleId": "m04", "questions": [{"id": "m04-q01", "type": "single", "prompt": "What is the core principle behind differential GNSS (DGNSS)?", "explanation": "The reference station knows where it really is, so it can estimate errors that nearby users experience similarly.", "options": [{"id": "b9f086", "text": "A second receiver on the same vehicle doubles the number of measurements."}, {"id": "a1a197", "text": "A receiver at a precisely surveyed location can estimate correlated errors and supply corrections to nearby users."}, {"id": "852409", "text": "Satellites transmit a second, more accurate signal for paying users."}, {"id": "5d51de", "text": "The user receiver averages its position over a long period."}], "answer": "a1a197"}, {"id": "m04-q02", "type": "single", "prompt": "Why does a DGNSS correction become less useful as the user moves farther from the reference station?", "explanation": "Correlation between user and reference errors weakens with distance, so the correction becomes less representative.", "options": [{"id": "2604cf", "text": "Corrections are encrypted by distance."}, {"id": "18710f", "text": "Some errors, especially spatially varying atmospheric effects, decorrelate with distance."}, {"id": "4bc51a", "text": "The reference station can only see satellites directly overhead."}, {"id": "2b62ea", "text": "Radio links always fail beyond 1 km."}], "answer": "18710f"}, {"id": "m04-q03", "type": "multi", "prompt": "Beyond an accuracy figure, which requirements may a correction-based architecture need?", "explanation": "Corrections are time-sensitive and delivered over a link, so their timeliness and failure behaviour must be specified.", "options": [{"id": "94f346", "text": "Correction update rate"}, {"id": "aa55c5", "text": "Maximum correction age and end-to-end latency"}, {"id": "f52ce0", "text": "Behaviour when corrections are lost"}, {"id": "01179e", "text": "Communications availability"}, {"id": "7e0888", "text": "The colour of the reference station enclosure"}], "answer": "01179e,94f346,aa55c5,f52ce0"}, {"id": "m04-q04", "type": "single", "prompt": "Why is SBAS described as \"not just more accurate GPS\"?", "explanation": "SBAS provides corrections and integrity-related information. For safety-of-life use, the integrity role is especially important.", "options": [{"id": "a2a327", "text": "Because it only works for GLONASS."}, {"id": "46f91b", "text": "Because, for supported safety services, it provides integrity information enabling users to know whether to rely on the service within defined protection and alerting limits."}, {"id": "35610b", "text": "Because it replaces the GNSS constellations entirely."}, {"id": "7c7dfe", "text": "Because it provides centimetre-level accuracy everywhere."}], "answer": "46f91b"}, {"id": "m04-q05", "type": "match", "prompt": "Match each SBAS to its region.", "explanation": "SBAS performance and services vary by system and service definition, so engineers should consult the applicable documents.", "left": [{"id": "807261", "text": "EGNOS"}, {"id": "88245c", "text": "WAAS"}, {"id": "f4ccd5", "text": "MSAS"}, {"id": "01f7bf", "text": "GAGAN"}], "right": [{"id": "322626", "text": "Japan"}, {"id": "4a8885", "text": "Europe"}, {"id": "57bb4f", "text": "India"}, {"id": "fab08e", "text": "United States"}], "answer": "01f7bf=57bb4f;807261=4a8885;88245c=fab08e;f4ccd5=322626"}, {"id": "m04-q06", "type": "single", "prompt": "What makes carrier-phase measurements central to RTK?", "explanation": "Carrier phase is precise but ambiguous. RTK resolves the integer ambiguities using simultaneous base and rover observations.", "options": [{"id": "39aec2", "text": "They are unambiguous from the moment of acquisition."}, {"id": "423179", "text": "They are extremely precise, and once the integer ambiguities are resolved they enable centimetre-level relative positioning."}, {"id": "8f4f8d", "text": "They remove the need for a reference station."}, {"id": "018b99", "text": "They are immune to multipath."}], "answer": "423179"}, {"id": "m04-q07", "type": "single", "prompt": "An RTK receiver reports a \"float\" solution. What does this mean?", "explanation": "Fixed means the integer ambiguities are resolved and validated. Float means they are not, so performance is lower.", "options": [{"id": "b99e79", "text": "The carrier ambiguities have not yet been reliably fixed to integers, so precision is generally poorer than a fixed solution."}, {"id": "6f3009", "text": "The receiver has full centimetre-level accuracy."}, {"id": "79ce70", "text": "The receiver has lost all satellites."}, {"id": "f9f534", "text": "The base station is floating on water."}], "answer": "b99e79"}, {"id": "m04-q08", "type": "truefalse", "prompt": "If a system is \"RTK enabled\", it is always delivering centimetre-level accuracy.", "explanation": "An RTK-capable system may not currently hold a fixed solution. Performance depends on ambiguity resolution, geometry, baseline, atmosphere, corrections and communications.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m04-q09", "type": "single", "prompt": "What is a key consequence of increasing the RTK baseline length?", "explanation": "Longer baselines weaken the correlated-error assumption. Network RTK exists partly to address this.", "options": [{"id": "53804d", "text": "Ambiguity resolution becomes easier."}, {"id": "365a8a", "text": "Errors at base and rover become less correlated, atmospheric differences grow and ambiguity resolution can become harder."}, {"id": "18e2f3", "text": "The rover no longer needs corrections."}, {"id": "9a72a9", "text": "Baseline length has no effect on RTK."}], "answer": "365a8a"}, {"id": "m04-q10", "type": "match", "prompt": "Match each technique to its main source of strength.", "explanation": "Each technique solves a different problem with different dependencies; they are not simply rungs on an accuracy ladder.", "left": [{"id": "969d9b", "text": "RTK"}, {"id": "c9273a", "text": "PPP"}, {"id": "cbaa09", "text": "SBAS"}, {"id": "6d19a8", "text": "DGNSS"}], "right": [{"id": "006350", "text": "Wide-area corrections and integrity information broadcast via geostationary satellites"}, {"id": "235062", "text": "Code or range corrections from a known reference station"}, {"id": "df1c6d", "text": "Precise global satellite orbit and clock products plus detailed modelling at the user"}, {"id": "ee2afc", "text": "Spatially correlated measurements at a nearby reference"}], "answer": "6d19a8=235062;969d9b=ee2afc;c9273a=df1c6d;cbaa09=006350"}, {"id": "m04-q11", "type": "single", "prompt": "A mission requires 5 cm accuracy within 10 seconds of start-up. A PPP service eventually reaches 3 cm after a long convergence period. What is the correct assessment?", "explanation": "A system that eventually reaches the accuracy may still fail the mission if it cannot do so in the required time.", "options": [{"id": "055c28", "text": "It meets the requirement because 3 cm is better than 5 cm."}, {"id": "36b196", "text": "It may not meet the requirement: accuracy and time-to-accuracy are separate requirements."}, {"id": "5d6ab1", "text": "PPP never reaches centimetre-level accuracy."}, {"id": "e79647", "text": "Convergence time is irrelevant for high-accuracy systems."}], "answer": "36b196"}, {"id": "m04-q12", "type": "truefalse", "prompt": "PPP-RTK, network RTK and SSR are standardised terms used identically by every provider.", "explanation": "Terminology varies. Ask what correction information is actually supplied and how the receiver uses it, rather than relying on the label.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m04-q13", "type": "single", "prompt": "A high-accuracy system receives corrections over a mobile data network. Which statement best reflects the module's resilience lesson?", "explanation": "Improving accuracy can add dependencies. Better accuracy is not automatically better resilience.", "options": [{"id": "3e4952", "text": "Adding corrections always improves resilience because accuracy improves."}, {"id": "4aaf54", "text": "The correction path becomes part of the PNT architecture, adding dependencies such as communications, processing and service credentials."}, {"id": "8101dc", "text": "Corrections cannot fail once the receiver has a fixed solution."}, {"id": "13c43f", "text": "Communications are outside the scope of PNT engineering."}], "answer": "4aaf54"}, {"id": "m04-q14", "type": "single", "prompt": "A supplier says \"we use RTK, so our PNT is resilient\". What is the best response?", "explanation": "High accuracy does not prove integrity or resilience. A centimetre-level receiver can still be vulnerable to interference, spoofing or bad corrections.", "options": [{"id": "cb5594", "text": "Agree, because RTK is the most accurate technique."}, {"id": "bd60c2", "text": "The conclusion does not follow: RTK is a positioning technique, and resilience requires analysis of threats, failure modes, dependencies, detection, fallback and recovery."}, {"id": "14830c", "text": "Agree, provided it is network RTK."}, {"id": "3522f3", "text": "Disagree, because RTK cannot be used in resilient systems."}], "answer": "bd60c2"}, {"id": "m04-q15", "type": "single", "prompt": "A safety-related aviation application is choosing an augmentation approach. What should drive the selection?", "explanation": "Surveying, autonomy and aviation can all use augmented GNSS, but their acceptance criteria differ. Never select from the accuracy figure alone.", "options": [{"id": "5f5def", "text": "The smallest possible accuracy figure on the datasheet."}, {"id": "353198", "text": "Integrity, alerting and defined service performance within the supported service area."}, {"id": "b4b2c1", "text": "Whichever technique has the shortest name."}, {"id": "0c73e5", "text": "The cheapest receiver available."}], "answer": "353198"}]}, {"moduleId": "m05", "questions": [{"id": "m05-q01", "type": "match", "prompt": "Classify each source by the type of information it provides.", "explanation": "Absolute sources reference something external; relative sources propagate from a known state; hybrids let one constrain the weaknesses of another.", "left": [{"id": "10cbd1", "text": "eLoran"}, {"id": "b2e390", "text": "Wheel odometry"}, {"id": "639921", "text": "GNSS + INS integration"}], "right": [{"id": "7ddcb9", "text": "Absolute / externally referenced"}, {"id": "a5b189", "text": "Hybrid of absolute and relative"}, {"id": "ac112d", "text": "Relative / self-contained"}], "answer": "10cbd1=7ddcb9;639921=a5b189;b2e390=ac112d"}, {"id": "m05-q02", "type": "match", "prompt": "Match each inertial sensor to what it measures.", "explanation": "An IMU typically contains accelerometers and gyroscopes. A magnetometer is sometimes integrated but is not intrinsically an inertial sensor.", "left": [{"id": "565e75", "text": "Accelerometer"}, {"id": "0e72ab", "text": "Gyroscope"}, {"id": "caa983", "text": "Magnetometer"}], "right": [{"id": "315baf", "text": "Local magnetic field, giving heading-related information"}, {"id": "857013", "text": "Angular rate or rotation"}, {"id": "e1df4c", "text": "Specific force along an axis"}], "answer": "0e72ab=857013;565e75=e1df4c;caa983=315baf"}, {"id": "m05-q03", "type": "order", "prompt": "Put the INS mechanisation steps in a sensible order.", "explanation": "Known initial state + measured rotation + measured acceleration → propagated position, velocity and attitude.", "items": [{"id": "0a230e", "text": "Integrate velocity to estimate position"}, {"id": "31e02f", "text": "Start from a known initial position, velocity and attitude"}, {"id": "5d24db", "text": "Integrate acceleration to estimate velocity"}, {"id": "76a4fb", "text": "Transform measured acceleration into the navigation frame and account for gravity"}, {"id": "a88566", "text": "Integrate angular-rate measurements to update orientation"}], "answer": "31e02f>a88566>76a4fb>5d24db>0a230e"}, {"id": "m05-q04", "type": "single", "prompt": "Why is accelerometer bias particularly damaging in inertial navigation?", "explanation": "Double integration makes a small bias grow rapidly. Drift is unbounded without an external constraint.", "options": [{"id": "297cad", "text": "Because it only affects heading."}, {"id": "982b2f", "text": "Because it is integrated to velocity and then again to position, so a small persistent error grows into a substantial position error."}, {"id": "c35720", "text": "Because accelerometers cannot be calibrated."}, {"id": "ea5a01", "text": "Because it causes GNSS signals to be lost."}], "answer": "982b2f"}, {"id": "m05-q05", "type": "single", "prompt": "A proposal states \"the platform has an IMU, so it can navigate without GNSS\". What is the most useful response?", "explanation": "Inertial sensors span a huge performance range. \"Has an IMU\" says almost nothing about navigation performance.", "options": [{"id": "9f4cb3", "text": "Accept it: all IMUs provide equivalent navigation performance."}, {"id": "944890", "text": "Ask about sensor grade, bias stability, alignment, calibration, environmental limits and demonstrated drift over the required outage duration."}, {"id": "4d5b4f", "text": "Reject it: IMUs cannot be used for navigation."}, {"id": "1d2c13", "text": "Ask only for the IMU's update rate."}], "answer": "944890"}, {"id": "m05-q06", "type": "truefalse", "prompt": "Adding more sensors to a fusion filter always improves the navigation solution.", "explanation": "Poor calibration, incorrect uncertainty models, correlated errors or a faulty sensor can degrade a fused estimate. Fusion needs monitoring and fault handling.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m05-q07", "type": "single", "prompt": "What is clock holdover?", "explanation": "Holdover is the timing equivalent of inertial drift: it bridges outages, but uncertainty grows.", "options": [{"id": "0b5d72", "text": "The time taken for a clock to warm up after power-on."}, {"id": "e2da61", "text": "The ability of a timing system to maintain an acceptable time estimate after its external reference is lost, with uncertainty growing over time."}, {"id": "6d3398", "text": "A method of distributing time over a network."}, {"id": "521907", "text": "A permanent replacement for GNSS timing."}], "answer": "e2da61"}, {"id": "m05-q08", "type": "match", "prompt": "Match each timing term to its meaning.", "explanation": "A system can be well syntonised yet retain a time offset. High resolution does not by itself imply high accuracy.", "left": [{"id": "b94b4d", "text": "Synchronisation"}, {"id": "6a4ce9", "text": "Syntonisation"}, {"id": "72d1e9", "text": "Allan deviation"}, {"id": "f37af1", "text": "Resolution"}], "right": [{"id": "3ad0d5", "text": "Agreement in time or phase between clocks"}, {"id": "6ec1f7", "text": "Statistical measure of frequency stability over different averaging times"}, {"id": "99c744", "text": "Smallest increment that can be represented or measured"}, {"id": "dcf0bc", "text": "Agreement in frequency, so clocks advance at the same rate"}], "answer": "6a4ce9=dcf0bc;72d1e9=6ec1f7;b94b4d=3ad0d5;f37af1=99c744"}, {"id": "m05-q09", "type": "single", "prompt": "Which requirement best turns clock holdover into something testable?", "explanation": "A testable requirement states the allowable time error and the holdover duration it must be maintained for.", "options": [{"id": "2dab4e", "text": "\"The clock shall be highly stable.\""}, {"id": "00a972", "text": "\"The system shall use a rubidium oscillator.\""}, {"id": "b8722a", "text": "\"Maintain time within a stated error of UTC for a stated duration after loss of the primary external reference.\""}, {"id": "bd24a4", "text": "\"The clock shall provide resilient timing.\""}], "answer": "b8722a"}, {"id": "m05-q10", "type": "single", "prompt": "A site has an excellent local atomic clock, but applications report poor time accuracy. Which explanation is consistent with the module?", "explanation": "Generating time is not the same as distributing it. Trace the timing chain to where time is actually used.", "options": [{"id": "b82dc9", "text": "An accurate clock guarantees every consuming component has accurate time."}, {"id": "bb8181", "text": "The fault may lie in time distribution, such as network delay, asymmetry, missing hardware timestamping or configuration."}, {"id": "3f8e62", "text": "Atomic clocks cannot provide UTC."}, {"id": "d2a842", "text": "The problem must be GNSS jamming."}], "answer": "bb8181"}, {"id": "m05-q11", "type": "single", "prompt": "What is the main engineering value of eLoran as a complement to GNSS?", "explanation": "The value is the different failure mode and propagation path, not merely the existence of a second radio signal.", "options": [{"id": "b16fe5", "text": "It is simply ground-based GPS with identical characteristics."}, {"id": "d6b486", "text": "It uses powerful terrestrial low-frequency transmitters with different propagation and failure modes, providing useful source diversity."}, {"id": "2a06fe", "text": "It provides centimetre-level accuracy everywhere."}, {"id": "74ccbf", "text": "It requires no infrastructure."}], "answer": "d6b486"}, {"id": "m05-q12", "type": "single", "prompt": "Why is a signal of opportunity not automatically an assured PNT service?", "explanation": "Using existing emitters is attractive, but the signal was not designed or guaranteed as a navigation service.", "options": [{"id": "dc6d93", "text": "Because it can never be used for positioning."}, {"id": "465db5", "text": "Because it was created for another purpose, and the owner can change the waveform, timing, transmitter location or availability."}, {"id": "e03952", "text": "Because it always depends on GNSS."}, {"id": "15aabe", "text": "Because it only works indoors."}], "answer": "465db5"}, {"id": "m05-q13", "type": "single", "prompt": "A LEO-based navigation service determines its satellite orbits and time using GNSS. What does this mean for resilience?", "explanation": "Different product names do not mean independence. Trace the complete dependency chain for each source.", "options": [{"id": "8b7091", "text": "It is fully independent of GNSS because it uses different satellites."}, {"id": "dcddda", "text": "A GNSS failure could propagate into the LEO service, creating a common-mode dependency."}, {"id": "818564", "text": "LEO satellites cannot use GNSS."}, {"id": "4a62d0", "text": "It makes the LEO service immune to interference."}], "answer": "dcddda"}, {"id": "m05-q14", "type": "multi", "prompt": "Which statements about emerging quantum and AI/ML-assisted PNT reflect the module's guidance?", "explanation": "Labels do not establish readiness. Assess performance, maturity, SWaP, dependencies and evidence in the intended environment.", "options": [{"id": "c21adb", "text": "Quantum PNT is a family of developing technologies, not a finished replacement for GPS."}, {"id": "93884c", "text": "An AI-enabled estimator may behave unpredictably outside its training and validation conditions."}, {"id": "869048", "text": "Technology maturity should be treated as an assurance claim to be evidenced."}, {"id": "894b61", "text": "A \"quantum\" or \"AI-enabled\" label establishes operational readiness."}], "answer": "869048,93884c,c21adb"}, {"id": "m05-q15", "type": "single", "prompt": "A vehicle enters a long tunnel and loses GNSS. Which statement best describes a well-engineered integrated system?", "explanation": "Dead reckoning can bridge the outage, but uncertainty grows. A good system knows and reports the uncertainty of its propagated solution.", "options": [{"id": "42dece", "text": "The navigation solution fails immediately at the tunnel portal."}, {"id": "fdbf12", "text": "The solution stays as accurate as it was with GNSS for the whole tunnel."}, {"id": "720b1d", "text": "The INS, wheel speed and map constraints propagate the solution while its uncertainty grows, and GNSS re-constrains it at the exit."}, {"id": "a3efdf", "text": "The system should stop reporting position until GNSS returns."}], "answer": "720b1d"}]}, {"moduleId": "m06", "questions": [{"id": "m06-q01", "type": "match", "prompt": "Match each concept to the correct PNT example.", "explanation": "Separating cause from effect keeps threat modelling mission-led rather than a list of hostile techniques.", "left": [{"id": "2d32c9", "text": "Threat / adverse condition"}, {"id": "d52348", "text": "Vulnerability"}, {"id": "ad1086", "text": "PNT harm"}, {"id": "b00df2", "text": "Mission consequence"}], "right": [{"id": "6a3a91", "text": "A single antenna shared by both receivers"}, {"id": "92dd2b", "text": "Autonomy restricted and synchronisation lost"}, {"id": "b84219", "text": "Space weather disturbing the ionosphere"}, {"id": "bb6cd4", "text": "Timing reference biased and integrity lost"}], "answer": "2d32c9=b84219;ad1086=bb6cd4;b00df2=92dd2b;d52348=6a3a91"}, {"id": "m06-q02", "type": "match", "prompt": "Match each failure state to what the user experiences.", "explanation": "Classifying the effect on the user keeps the analysis focused on operational consequence.", "left": [{"id": "7b96c0", "text": "Denied / unavailable"}, {"id": "6366f2", "text": "Degraded"}, {"id": "b0631f", "text": "Deceived / misleading"}], "right": [{"id": "d3fc0d", "text": "PNT appears usable but is materially wrong"}, {"id": "efd7b0", "text": "PNT remains available but no longer meets required performance"}, {"id": "f6c5f4", "text": "Required PNT information cannot be obtained"}], "answer": "6366f2=efd7b0;7b96c0=f6c5f4;b0631f=d3fc0d"}, {"id": "m06-q03", "type": "single", "prompt": "Why is deception often a more serious integrity hazard than denial?", "explanation": "Misleading information can propagate unnoticed. That makes it a particularly important integrity hazard.", "options": [{"id": "d67223", "text": "Because deception is always more expensive for the attacker."}, {"id": "7bc9f2", "text": "Because a clean loss can trigger a fallback, whereas convincing but wrong PNT may keep driving automation and human decisions."}, {"id": "52f276", "text": "Because denial cannot affect timing systems."}, {"id": "efab31", "text": "Because deceived receivers always shut down."}], "answer": "7bc9f2"}, {"id": "m06-q04", "type": "single", "prompt": "Why are GNSS signals particularly susceptible to radio-frequency interference?", "explanation": "Weak received signals make GNSS useful but mean local RF energy can interfere with reception.", "options": [{"id": "85a2fe", "text": "Because they are transmitted at very high power."}, {"id": "1a422c", "text": "Because they travel thousands of kilometres and arrive at very low received power in a noisy RF environment."}, {"id": "f5d936", "text": "Because GNSS receivers do not use antennas."}, {"id": "cb4fbf", "text": "Because GNSS uses only one frequency worldwide."}], "answer": "1a422c"}, {"id": "m06-q05", "type": "truefalse", "prompt": "Every GNSS interference event should be described as jamming.", "explanation": "Interference is unwanted RF energy; jamming is deliberate interference. Report what the evidence supports, for example \"GNSS interference was observed\".", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m06-q06", "type": "multi", "prompt": "Which observations could indicate jamming or a common RF problem?", "explanation": "Losing one satellite can be normal. Many signals degrading together suggests a common RF problem; detection relies on patterns and independent evidence.", "options": [{"id": "1ee367", "text": "Carrier-to-noise falling across several unrelated satellites at once"}, {"id": "59361a", "text": "Multiple nearby systems losing GNSS at a similar time"}, {"id": "f41f02", "text": "An INS continuing normally while GNSS measurements disappear"}, {"id": "580317", "text": "One satellite setting below the horizon"}], "answer": "1ee367,59361a,f41f02"}, {"id": "m06-q07", "type": "single", "prompt": "What distinguishes spoofing from jamming?", "explanation": "Spoofing is deception rather than obvious loss of service, and a spoofed solution may initially appear plausible.", "options": [{"id": "821cc7", "text": "Spoofing only affects timing; jamming only affects position."}, {"id": "ab9191", "text": "Spoofing aims to make a receiver compute a false but plausible solution, making it an integrity problem; jamming aims to deny or degrade reception."}, {"id": "7272ac", "text": "Spoofing is always accidental."}, {"id": "f16f9b", "text": "There is no difference; they are synonyms."}], "answer": "ab9191"}, {"id": "m06-q08", "type": "single", "prompt": "What does meaconing demonstrate about authentication?", "explanation": "Meaconing rebroadcasts genuine signals, often with delay or from another location, so the propagation context is altered.", "options": [{"id": "52f2f4", "text": "Authenticated signals can never be misleading."}, {"id": "5dc1d0", "text": "Authentic source data does not prove the signal arrived through the expected path, at the expected time, without delay or rebroadcast."}, {"id": "bf546d", "text": "Meaconing only works on unauthenticated military signals."}, {"id": "e88da0", "text": "Authentication prevents all forms of deception."}], "answer": "5dc1d0"}, {"id": "m06-q09", "type": "single", "prompt": "A correction service is compromised and delivers subtly biased corrections. Which statement is correct?", "explanation": "PNT assurance is cyber-physical. Software, data, networks and interfaces are attack and failure surfaces too.", "options": [{"id": "eaec67", "text": "This cannot affect PNT because the satellite signals are untouched."}, {"id": "11842d", "text": "It is a data-layer threat that can bias a high-accuracy solution without any attack on the RF signal."}, {"id": "9061df", "text": "Only the RF front end needs protecting."}, {"id": "480975", "text": "It will always cause total loss of service."}], "answer": "11842d"}, {"id": "m06-q10", "type": "single", "prompt": "A design uses two GNSS receivers for redundancy. Which finding would reveal a hidden single point of failure?", "explanation": "A design that looks redundant on a block diagram can hide shared antennas, power, software, correction providers or network paths.", "options": [{"id": "0dc285", "text": "The receivers are from different manufacturers."}, {"id": "518ea4", "text": "Both receivers share the same antenna and power supply."}, {"id": "d806c6", "text": "The receivers are mounted a metre apart."}, {"id": "2b2c93", "text": "One receiver is newer than the other."}], "answer": "518ea4"}, {"id": "m06-q11", "type": "single", "prompt": "A supplier says their timing service is \"independent\" of your GNSS receiver. What should you establish?", "explanation": "Independence has to hold under the real-world failure, not merely look different at the interface.", "options": [{"id": "660c26", "text": "Only whether its interface looks different."}, {"id": "a91c75", "text": "What it depends on upstream, because independence must survive the failure being analysed; for example, it may itself be disciplined by GNSS."}, {"id": "b31b6d", "text": "Whether it is cheaper than GNSS."}, {"id": "e650fc", "text": "Whether it uses the same connector type."}], "answer": "a91c75"}, {"id": "m06-q12", "type": "order", "prompt": "Put the stages of the PNT risk lifecycle in order.", "explanation": "The lifecycle, aligned with NIST CSF 2.0, connects governance and dependency identification with protection, detection, response and recovery.", "items": [{"id": "1ee383", "text": "Detect"}, {"id": "868f79", "text": "Identify"}, {"id": "98dbce", "text": "Govern"}, {"id": "ce81d6", "text": "Recover"}, {"id": "e1d994", "text": "Protect"}, {"id": "f5ab3f", "text": "Respond"}], "answer": "98dbce>868f79>e1d994>1ee383>f5ab3f>ce81d6"}, {"id": "m06-q13", "type": "single", "prompt": "GNSS returns after a suspected spoofing incident. What should the system do?", "explanation": "Recovery is not simply \"GNSS is back\". Trusting the first returning signal can preserve a corrupted solution.", "options": [{"id": "ae1990", "text": "Immediately trust the first returning signal to restore full service."}, {"id": "f57a9d", "text": "Revalidate sources against independent information and restore trust under defined criteria before resuming full reliance."}, {"id": "9aa48e", "text": "Permanently disable GNSS."}, {"id": "c1959b", "text": "Reset the system to factory defaults."}], "answer": "f57a9d"}, {"id": "m06-q14", "type": "single", "prompt": "A vessel's GNSS position diverges from its route while the receiver reports a valid fix. What is the correct first priority?", "explanation": "Detection of misleading PNT is about inconsistency with independent truth or physics. Attribution is secondary to a timely safe response.", "options": [{"id": "2bc3d5", "text": "Determine whether the cause is spoofing before doing anything else."}, {"id": "7809a6", "text": "Compare GNSS with independent sources and, if they disagree beyond expected uncertainty, treat GNSS as suspect and respond safely; attribution can come later."}, {"id": "c12554", "text": "Trust the receiver because it reports a valid fix."}, {"id": "1a4fbf", "text": "Switch off all navigation systems."}], "answer": "7809a6"}, {"id": "m06-q15", "type": "single", "prompt": "Which statement about graceful degradation is correct?", "explanation": "\"Resilient to GNSS loss\" is not measurable until duration, performance and behaviour in each state are specified.", "options": [{"id": "189a22", "text": "A system is either fully operational or failed; intermediate states add risk."}, {"id": "5d799f", "text": "Defined intermediate states (degraded, restricted, safe state, recovery) let the system retain useful capability while reducing function or confidence explicitly."}, {"id": "7ff09e", "text": "Graceful degradation means hiding degraded performance from the user."}, {"id": "9434ed", "text": "It only applies to timing systems."}], "answer": "5d799f"}]}, {"moduleId": "m07", "questions": [{"id": "m07-q01", "type": "single", "prompt": "Which of these is an engineering resilience requirement rather than a technology statement?", "explanation": "A requirement defines the capability that must survive, its performance, duration and detection behaviour.", "options": [{"id": "866dc6", "text": "\"Fit a backup GPS receiver.\""}, {"id": "7df5ce", "text": "\"Use GPS, Galileo and BeiDou.\""}, {"id": "175f1d", "text": "\"Maintain horizontal position within 20 m for 15 minutes after loss of trusted GNSS, with a warning within 5 seconds if the bound cannot be maintained.\""}, {"id": "259d2a", "text": "\"The system shall be resilient.\""}], "answer": "175f1d"}, {"id": "m07-q02", "type": "match", "prompt": "Match each concept to its example.", "explanation": "Redundancy is necessary but not sufficient. Resilience improves when it is combined with diversity, dissimilarity and genuine independence.", "left": [{"id": "61cca6", "text": "Redundancy"}, {"id": "2d1980", "text": "Diversity"}, {"id": "c99521", "text": "Dissimilarity"}, {"id": "27c5a8", "text": "Independence"}], "right": [{"id": "12e927", "text": "A timing path with a separate reference, transport, power and local holdover"}, {"id": "3b776d", "text": "Two GNSS receivers"}, {"id": "71bcc5", "text": "GNSS plus terrestrial radio PNT"}, {"id": "d84e96", "text": "GNSS radio ranging plus inertial dead reckoning plus terrain matching"}], "answer": "27c5a8=12e927;2d1980=71bcc5;61cca6=3b776d;c99521=d84e96"}, {"id": "m07-q03", "type": "match", "prompt": "Match each resilience function to an illustrative example.", "explanation": "Passive resistance reduces harm; active detection, response and recovery preserve and restore trusted capability.", "left": [{"id": "c4a5f8", "text": "Resistance"}, {"id": "90f775", "text": "Detection"}, {"id": "40cb2d", "text": "Response"}, {"id": "cfc9cf", "text": "Recovery"}], "right": [{"id": "1d9e9b", "text": "Integrity monitoring and cross-source comparison"}, {"id": "bae3d6", "text": "Robust installation and hardened configuration"}, {"id": "bf50d7", "text": "Revalidating the returning source before controlled reintegration"}, {"id": "e149e2", "text": "Excluding suspect data and entering a degraded mode"}], "answer": "40cb2d=e149e2;90f775=1d9e9b;c4a5f8=bae3d6;cfc9cf=bf50d7"}, {"id": "m07-q04", "type": "single", "prompt": "A GNSS receiver is outputting coordinates at the expected rate. Why might a resilient architecture still refuse to use them?", "explanation": "Each source should be monitored for freshness, quality, uncertainty, plausibility, consistency and configuration before fusion.", "options": [{"id": "754f82", "text": "Because receivers should never be used when they are available."}, {"id": "28f4ef", "text": "Because \"available\" is not the same as \"healthy\": the data may be stale, inconsistent, implausible or outside demonstrated conditions."}, {"id": "466f6b", "text": "Because fusion algorithms reject all GNSS data by default."}, {"id": "4dfb6f", "text": "Because coordinates are not PNT information."}], "answer": "28f4ef"}, {"id": "m07-q05", "type": "truefalse", "prompt": "The architecture must prove whether GNSS was spoofed before it is allowed to exclude GNSS from the solution.", "explanation": "Detection is not attribution. Safe behaviour should not depend on immediate root-cause attribution.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m07-q06", "type": "order", "prompt": "Put the resilient PNT modes in the order a platform would move through them during a GNSS outage that becomes progressively worse and then clears.", "explanation": "Each mode has defined entry conditions and behaviour; recovery requires revalidation before normal operation is restored.", "items": [{"id": "27a2e7", "text": "NORMAL RESTORED"}, {"id": "3bfd01", "text": "UNAVAILABLE / SAFE"}, {"id": "3d0098", "text": "RECOVERY / REVALIDATION"}, {"id": "5057bc", "text": "NORMAL"}, {"id": "6b2bd5", "text": "DEGRADED"}, {"id": "cf7aa9", "text": "RESTRICTED"}], "answer": "5057bc>6b2bd5>cf7aa9>3bfd01>3d0098>27a2e7"}, {"id": "m07-q07", "type": "single", "prompt": "What does a supervisory PNT manager do?", "explanation": "It manages behaviour across the whole chain, not simply picking the most accurate-looking source.", "options": [{"id": "38d283", "text": "Selects whichever source advertises the smallest accuracy figure."}, {"id": "7a6f17", "text": "Controls source enablement, health state, mode transitions, failover, holdover, degraded operation, alerts and recovery criteria."}, {"id": "929a31", "text": "Replaces the need for source monitoring."}, {"id": "07624b", "text": "Only logs data for later analysis."}], "answer": "7a6f17"}, {"id": "m07-q08", "type": "multi", "prompt": "When designing a failover transition, which should be defined?", "explanation": "Failover is a controlled transition, not merely a switch. Sources can differ in reference frames, biases, rates and uncertainties.", "options": [{"id": "ec2829", "text": "Which source becomes authoritative"}, {"id": "ff3909", "text": "How state continuity is maintained without an unsafe position or time jump"}, {"id": "95a2e6", "text": "What uncertainty applies immediately after transition"}, {"id": "bba06d", "text": "What mode status and restrictions are exposed to the application"}, {"id": "8c90ac", "text": "The paint colour of the backup unit"}], "answer": "95a2e6,bba06d,ec2829,ff3909"}, {"id": "m07-q09", "type": "single", "prompt": "In a deception scenario, GNSS remains available but diverges from INS, odometry and map constraints. What must fusion NOT do?", "explanation": "Averaging blindly lets a bad source pull the solution away from truth. A robust architecture must distrust a source that is still producing data.", "options": [{"id": "fbb6b7", "text": "Quarantine GNSS while the anomaly is assessed."}, {"id": "3c7ba8", "text": "Simply average or compromise between the suspect GNSS and the independent sources."}, {"id": "921bdd", "text": "Alert the application with a suspect-source state."}, {"id": "3a0944", "text": "Maintain a degraded solution with explicit uncertainty."}], "answer": "3c7ba8"}, {"id": "m07-q10", "type": "single", "prompt": "Why is hysteresis used in recovery criteria?", "explanation": "Using different criteria or persistence periods for failure and recovery prevents unstable behaviour.", "options": [{"id": "9cae27", "text": "To speed up reintegration of any returning source."}, {"id": "c17946", "text": "To stop a marginal source repeatedly entering and leaving the solution, which creates unstable mode flapping."}, {"id": "84a5fd", "text": "To increase the holdover duration of the clock."}, {"id": "3830a4", "text": "To reduce the number of sources required."}], "answer": "c17946"}, {"id": "m07-q11", "type": "match", "prompt": "Match each recovery objective to its meaning.", "explanation": "Both are application-specific engineering measures derived from the mission, not universal constants.", "left": [{"id": "ab95a5", "text": "Recovery point objective"}, {"id": "1722bf", "text": "Recovery time objective"}], "right": [{"id": "70815d", "text": "How quickly acceptable service must be restored"}, {"id": "8afdf8", "text": "Maximum tolerable PNT error or state loss during disruption"}], "answer": "1722bf=70815d;ab95a5=8afdf8"}, {"id": "m07-q12", "type": "single", "prompt": "What is the key architectural lesson from the NPLTime timing example?", "explanation": "NPL describes independent PTP feeds from separate hydrogen masers plus a local caesium clock for extended holdover at each node.", "options": [{"id": "f206e6", "text": "One highly accurate distribution path is enough."}, {"id": "256c25", "text": "Independent feeds plus local holdover clocks and monitoring reduce reliance on a single distribution path."}, {"id": "3db013", "text": "Timing resilience only requires a GNSS receiver."}, {"id": "12554f", "text": "Holdover provides unlimited backup."}], "answer": "256c25"}, {"id": "m07-q13", "type": "single", "prompt": "During a design review, which question most directly exposes hidden single points of failure?", "explanation": "Shared antennas, power, processing, time references, networks, reference data, firmware and location can defeat apparent redundancy.", "options": [{"id": "2e9e67", "text": "How many sources does the design have?"}, {"id": "af28de", "text": "For every backup, what does it share with the primary, and is that shared element monitored, redundant or accepted as residual risk?"}, {"id": "b5bfec", "text": "Which source is the most accurate?"}, {"id": "76a6da", "text": "How much does each source cost?"}], "answer": "af28de"}, {"id": "m07-q14", "type": "single", "prompt": "What is a useful adversarial test for a resilient fusion design?", "explanation": "The test reveals whether a high-confidence bad measurement can pull the fused solution away from truth.", "options": [{"id": "289323", "text": "Remove all sources simultaneously and check the system shuts down."}, {"id": "aaf748", "text": "Inject a plausible but biased source that is more confident than a correct independent source, and check the estimator identifies the inconsistency."}, {"id": "909c40", "text": "Run the system only in open sky."}, {"id": "c52524", "text": "Increase the update rate of every sensor."}], "answer": "aaf748"}, {"id": "m07-q15", "type": "single", "prompt": "A navigation subsystem correctly flags DEGRADED mode, but the autonomy stack ignores the flag and continues at full speed. What does this show?", "explanation": "A resilient PNT subsystem cannot guarantee safety if the consuming application ignores its uncertainty and mode information.", "options": [{"id": "21a91b", "text": "The navigation subsystem has failed its integrity requirement."}, {"id": "298bd3", "text": "Application-level resilience matters: the consumer must define and apply its own behaviour when PNT quality falls."}, {"id": "8c9ded", "text": "Mode flags are unnecessary."}, {"id": "4f9fe1", "text": "The autonomy stack should average the flags."}], "answer": "298bd3"}]}, {"moduleId": "m08", "questions": [{"id": "m08-q01", "type": "order", "prompt": "Put the stages of the top-down PNT systems-engineering flow in order.", "explanation": "Technology is introduced only after the required capability and tolerances are understood.", "items": [{"id": "132b1f", "text": "Interfaces"}, {"id": "3b8716", "text": "Mission / user need"}, {"id": "53ca8a", "text": "Verification evidence"}, {"id": "7c9249", "text": "Architecture"}, {"id": "7f019f", "text": "Requirements"}, {"id": "97d05a", "text": "PNT dependencies"}, {"id": "bec7f0", "text": "Use cases"}, {"id": "cf94b4", "text": "Risks"}], "answer": "3b8716>bec7f0>97d05a>cf94b4>7f019f>7c9249>132b1f>53ca8a"}, {"id": "m08-q02", "type": "single", "prompt": "A team opens a design meeting with \"we need RTK\". What is the best systems-engineering response?", "explanation": "Architecture is not the first step. Each technology choice should trace back to a mission need.", "options": [{"id": "8478a9", "text": "Start the RTK procurement immediately."}, {"id": "5bffc2", "text": "Ask what operational requirement led to that choice."}, {"id": "3f9abc", "text": "Replace RTK with PPP because it is newer."}, {"id": "1722ec", "text": "Add an INS as well, to be safe."}], "answer": "5bffc2"}, {"id": "m08-q03", "type": "single", "prompt": "Why is \"position accuracy shall be 1 m\" not yet a good requirement?", "explanation": "A good PNT requirement states what must be achieved under defined conditions, with statistical meaning and consequence.", "options": [{"id": "24bd51", "text": "Because 1 m is too accurate for any system."}, {"id": "1bc38e", "text": "Because it lacks operational purpose, coordinate frame, environment, confidence or statistical basis, and the consequence of exceeding it."}, {"id": "9591fe", "text": "Because accuracy should never be specified."}, {"id": "fd44c4", "text": "Because requirements must name a receiver model."}], "answer": "1bc38e"}, {"id": "m08-q04", "type": "single", "prompt": "When turning a user story into operational flows, which flows tend to expose resilience, failover, alerting and recovery requirements?", "explanation": "The normal path often produces performance requirements. The alternative paths expose the resilience requirements that are easily missed.", "options": [{"id": "fcd2e2", "text": "The normal success flow only."}, {"id": "2862e3", "text": "The alternative flows: degraded, misleading-source, extended outage and recovery."}, {"id": "dff99f", "text": "The flows that describe the user interface layout."}, {"id": "117ac3", "text": "None; resilience requirements come only from the supplier."}], "answer": "2862e3"}, {"id": "m08-q05", "type": "truefalse", "prompt": "Drawing the PNT system boundary removes the need to consider dependencies outside it.", "explanation": "The boundary establishes engineering responsibility, not independence. If failure outside the diagram can invalidate the PNT output, it is still a dependency.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m08-q06", "type": "match", "prompt": "Match each requirement category to an example.", "explanation": "Requirements should cover function, performance, resilience, interfaces, environment, security/assurance and lifecycle.", "left": [{"id": "cafdaa", "text": "Functional"}, {"id": "5567f4", "text": "Performance"}, {"id": "bb2236", "text": "Resilience"}, {"id": "3428af", "text": "Interface"}, {"id": "5556e1", "text": "Support / lifecycle"}], "right": [{"id": "36709e", "text": "Provide UTC-aligned time and a source-health state"}, {"id": "3b87bb", "text": "Holdover duration, degraded capability, failover and recovery behaviour"}, {"id": "a371e1", "text": "Coordinate frame, time scale, units, update rate and status fields"}, {"id": "b14b58", "text": "Calibration, software updates, obsolescence and re-test triggers"}, {"id": "bab82b", "text": "Accuracy, integrity, availability, continuity, latency and drift"}], "answer": "3428af=a371e1;5556e1=b14b58;5567f4=bab82b;bb2236=3b87bb;cafdaa=36709e"}, {"id": "m08-q07", "type": "single", "prompt": "Why is \"accuracy alone is insufficient\" when specifying PNT performance?", "explanation": "Specify the service the mission needs: accuracy, integrity, availability, continuity, latency, update rate, holdover and recovery.", "options": [{"id": "5cc3b4", "text": "Because accuracy cannot be measured."}, {"id": "5c27f6", "text": "Because a one-metre position that is stale, untrusted, in the wrong datum or unavailable at the critical moment may be useless."}, {"id": "9214a0", "text": "Because integrity is the only attribute that matters."}, {"id": "a4a7d5", "text": "Because accuracy is always guaranteed by GNSS."}], "answer": "5c27f6"}, {"id": "m08-q08", "type": "multi", "prompt": "Which elements belong in a complete resilience requirement statement?", "explanation": "Resilience is threat-relative and time-bounded, not a Boolean property.", "options": [{"id": "5ae859", "text": "The critical PNT capability that must survive"}, {"id": "6fc287", "text": "The threat, failure or adverse condition considered"}, {"id": "630186", "text": "The performance and duration that must be sustained"}, {"id": "709a36", "text": "The detection, degraded-mode and recovery behaviour required"}, {"id": "25dd07", "text": "The supplier's marketing tagline"}], "answer": "5ae859,630186,6fc287,709a36"}, {"id": "m08-q09", "type": "single", "prompt": "Why must system-level requirements be allocated to architectural functions?", "explanation": "Every critical requirement should point to a function that satisfies it, and every critical function should point back to a need or risk.", "options": [{"id": "59358c", "text": "To make the requirements document longer."}, {"id": "558e80", "text": "So that requirements such as \"detect misleading PNT\" have an architectural owner rather than remaining an aspiration."}, {"id": "b3ec8b", "text": "Because allocation replaces verification."}, {"id": "47a79f", "text": "So that suppliers can choose which requirements to meet."}], "answer": "558e80"}, {"id": "m08-q10", "type": "match", "prompt": "Match each architecture view to its purpose.", "explanation": "One diagram rarely communicates everything. Complementary views reveal different aspects of the same system.", "left": [{"id": "1a485a", "text": "Functional"}, {"id": "4b0db9", "text": "Logical"}, {"id": "6e0363", "text": "Physical"}, {"id": "08319a", "text": "Dependency / assurance"}], "right": [{"id": "085050", "text": "What the system must do"}, {"id": "145621", "text": "Where functions are implemented"}, {"id": "a8961a", "text": "What the system relies on"}, {"id": "ae09d2", "text": "How functions exchange information"}], "answer": "08319a=a8961a;1a485a=085050;4b0db9=ae09d2;6e0363=145621"}, {"id": "m08-q11", "type": "single", "prompt": "A high-quality PNT subsystem outputs uncertainty and integrity state, but the interface to the application passes only latitude, longitude and time. What is the risk?", "explanation": "Many PNT failures become system failures at interfaces. Uncertainty, integrity, freshness and mode information must survive to the consumer.", "options": [{"id": "0cea0c", "text": "None, because the PNT subsystem is high quality."}, {"id": "5e848a", "text": "The consumer cannot recognise degraded or untrusted PNT, so an otherwise good subsystem can still create an unsafe system."}, {"id": "fce43a", "text": "The coordinates will be in the wrong units."}, {"id": "1db395", "text": "The interface will run too slowly."}], "answer": "5e848a"}, {"id": "m08-q12", "type": "single", "prompt": "Which statement best reflects good trade-study discipline?", "explanation": "Vague conclusions are not traceable. Criteria include performance, resilience, independence, coverage, infrastructure, SWaP-C, integration, maturity, assurance and lifecycle.", "options": [{"id": "63b965", "text": "\"Option A is more resilient.\""}, {"id": "4761fc", "text": "Choose the option with the best headline accuracy in ideal conditions."}, {"id": "d19c83", "text": "Compare options against common mission-derived criteria, record assumptions and evidence, and state which threats and requirements drive the difference."}, {"id": "dd8cc3", "text": "Select the most mature technology regardless of requirements."}], "answer": "d19c83"}, {"id": "m08-q13", "type": "match", "prompt": "Match each anti-pattern to the better question to ask.", "explanation": "Anti-patterns look reasonable but hide missing conditions, triggers, durations or dependencies.", "left": [{"id": "556542", "text": "\"Dual GNSS"}, {"id": "c35268", "text": "\"Use INS as backup\""}, {"id": "f799dc", "text": "\"Return to normal when GNSS returns\""}, {"id": "d18420", "text": "\"Independent timing source\""}], "right": [{"id": "2d3417", "text": "What revalidation criteria restore trust?"}, {"id": "386072", "text": "Is it GNSS-disciplined upstream?"}, {"id": "971fc1", "text": "What error is permitted after the required bridging time?"}, {"id": "cbed02", "text": "resilient\" = Which failures are actually independent?"}], "answer": "556542=cbed02;c35268=971fc1;d18420=386072;f799dc=2d3417"}, {"id": "m08-q14", "type": "single", "prompt": "What role does a PNT requirements traceability matrix play?", "explanation": "Decide what evidence is needed early: a requirement that cannot be objectively verified is a requirements problem before it is a test problem.", "options": [{"id": "dd852a", "text": "It links mission need to requirements, architecture allocation, risks and planned verification methods, forming the engineering spine of the design."}, {"id": "f7b287", "text": "It lists every component's part number."}, {"id": "5216d5", "text": "It replaces the need for architecture diagrams."}, {"id": "3d5689", "text": "It is only produced after testing is complete."}], "answer": "dd852a"}, {"id": "m08-q15", "type": "single", "prompt": "Starting from \"the system needs resilient timing because GNSS may be unavailable\", what should come first?", "explanation": "The technology choice follows the requirement once the purpose, adverse condition, error bound, duration and recovery needs are defined.", "options": [{"id": "061f75", "text": "Select a caesium clock."}, {"id": "637100", "text": "Ask what the timing supports and what offset causes the operational service to fail."}, {"id": "76b2a7", "text": "Subscribe to an internet time service."}, {"id": "d98003", "text": "Write a test plan."}], "answer": "637100"}]}, {"moduleId": "m09", "questions": [{"id": "m09-q01", "type": "match", "prompt": "Match each concept to its core question.", "explanation": "A system can be verified against a poor requirement and still be unsuitable for the mission.", "left": [{"id": "9ec96e", "text": "Verification"}, {"id": "ddf43d", "text": "Validation"}, {"id": "81ee7e", "text": "Assurance"}], "right": [{"id": "2e9713", "text": "Is there a justified body of evidence supporting confidence in the critical claims?"}, {"id": "409abb", "text": "Did we build the system or requirement correctly?"}, {"id": "659cb9", "text": "Did we build the right capability for the intended mission and environment?"}], "answer": "81ee7e=2e9713;9ec96e=409abb;ddf43d=659cb9"}, {"id": "m09-q02", "type": "match", "prompt": "Match each IADT method to a PNT example.", "explanation": "Each method has limitations if used alone; a mature strategy combines them for the strongest evidence.", "left": [{"id": "0b8f49", "text": "Inspection"}, {"id": "025142", "text": "Analysis"}, {"id": "e6b81d", "text": "Demonstration"}, {"id": "f35af8", "text": "Test"}], "right": [{"id": "497ee3", "text": "Show a controlled transition from GNSS to alternate navigation"}, {"id": "6d41db", "text": "Review the architecture to confirm no undocumented shared antenna path"}, {"id": "ae2e71", "text": "Remove a source and measure detection, failover, error growth and recovery"}, {"id": "b98a1e", "text": "Predict INS drift or clock holdover against outage duration"}], "answer": "025142=b98a1e;0b8f49=6d41db;e6b81d=497ee3;f35af8=ae2e71"}, {"id": "m09-q03", "type": "single", "prompt": "What is the main limitation of demonstration when used alone?", "explanation": "Demonstration shows capability working, but resilience evidence also needs boundary and failure behaviour.", "options": [{"id": "da1d66", "text": "It cannot show the implemented system operating."}, {"id": "b30856", "text": "It can favour success paths and may not expose boundaries or failure cases."}, {"id": "2803a6", "text": "It requires reference truth accurate to the millimetre."}, {"id": "ea463b", "text": "It can only be used for timing systems."}], "answer": "b30856"}, {"id": "m09-q04", "type": "single", "prompt": "Which is the most verifiable version of \"the system shall detect spoofing\"?", "explanation": "A testable requirement defines the condition, behaviour, response time and threshold.", "options": [{"id": "ccc1a1", "text": "\"The system shall be spoof-proof.\""}, {"id": "0d4241", "text": "\"The system shall use an anti-spoofing receiver.\""}, {"id": "71f191", "text": "\"When GNSS becomes inconsistent with the defined independent references beyond the specified threshold, the system shall declare GNSS suspect within the required detection time and prevent it being presented as trusted.\""}, {"id": "652449", "text": "\"The system shall detect spoofing quickly.\""}], "answer": "71f191"}, {"id": "m09-q05", "type": "single", "prompt": "A receiver is claimed to achieve 10 cm accuracy, but the reference truth used in the trial has an uncertainty of about 8 cm. What is the concern?", "explanation": "The reference must be sufficiently better understood than the system under test, and its uncertainty recorded.", "options": [{"id": "add84e", "text": "None: any reference is acceptable."}, {"id": "adcc1d", "text": "The claimed performance is close to the reference uncertainty, so the evidence may not support the conclusion."}, {"id": "aa1826", "text": "The receiver must be more accurate than claimed."}, {"id": "60a424", "text": "Reference truth only matters for timing tests."}], "answer": "adcc1d"}, {"id": "m09-q06", "type": "multi", "prompt": "For a timing holdover test, which aspects of the measurement chain should be characterised?", "explanation": "A precise-looking measurement is not automatically strong evidence; the measurement chain's uncertainty must be understood.", "options": [{"id": "29de38", "text": "Traceability and calibration of the reference clock"}, {"id": "35185d", "text": "Cable, interface and transfer delays"}, {"id": "0d12b0", "text": "The measurement or averaging interval used"}, {"id": "4b3195", "text": "Environmental conditions relevant to the result"}, {"id": "777858", "text": "The brand of the laptop used to view results"}], "answer": "0d12b0,29de38,35185d,4b3195"}, {"id": "m09-q07", "type": "match", "prompt": "Match each test environment to its main strength.", "explanation": "Each environment has limitations too. Evidence should combine them and state what is not covered.", "left": [{"id": "a01307", "text": "Simulation / recorded data"}, {"id": "43897f", "text": "Laboratory / hardware-in-loop"}, {"id": "ead5e9", "text": "Field trial"}, {"id": "fa8925", "text": "Operational exercise"}], "right": [{"id": "33a15c", "text": "High operational realism"}, {"id": "720adb", "text": "Repeatable and safe with precise event control"}, {"id": "9188df", "text": "Controlled, instrumented and reproducible"}, {"id": "c96a7d", "text": "Real users, procedures and system interactions"}], "answer": "43897f=9188df;a01307=720adb;ead5e9=33a15c;fa8925=c96a7d"}, {"id": "m09-q08", "type": "single", "prompt": "Why should nominal performance be established before resilience testing?", "explanation": "Nominal performance is the baseline for interpreting behaviour under denial, degradation and deception.", "options": [{"id": "744cf3", "text": "Because nominal performance is the only thing that needs testing."}, {"id": "4ae2f7", "text": "Because without a baseline it is hard to distinguish a resilience failure from ordinary system performance."}, {"id": "acaf7d", "text": "Because resilience tests cannot be run without GNSS."}, {"id": "3bf1e1", "text": "Because the supplier requires it."}], "answer": "4ae2f7"}, {"id": "m09-q09", "type": "multi", "prompt": "Which metrics should be measured for detection performance?", "explanation": "A system that eventually notices a bad source may still fail the mission. Detection must be measured.", "options": [{"id": "f5ea76", "text": "Time to detect / time to alert"}, {"id": "eb0f08", "text": "Missed detections and false alarms"}, {"id": "22a95b", "text": "How much erroneous PNT reaches the application before isolation"}, {"id": "1e742f", "text": "Whether the correct integrity and mode state reaches the consumer in time"}, {"id": "6bb6f6", "text": "The number of satellites in the almanac"}], "answer": "1e742f,22a95b,eb0f08,f5ea76"}, {"id": "m09-q10", "type": "truefalse", "prompt": "Making detection thresholds as sensitive as possible is always the safest choice.", "explanation": "Over-sensitive thresholds cause nuisance alarms and unnecessary failovers; permissive thresholds let hazardous misleading information persist. The balance is mission and risk dependent.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "false"}, {"id": "m09-q11", "type": "single", "prompt": "A platform meets its 20 m requirement for 120 s of GNSS loss in straight-line motion but exceeds 20 m after 75 s during aggressive manoeuvres. What should the assurance statement say?", "explanation": "State what the evidence supports, bounded by configuration, environment, threat condition, duration and performance.", "options": [{"id": "9551ec", "text": "\"GNSS outage resilience passed.\""}, {"id": "44bd5a", "text": "\"The system is unusable.\""}, {"id": "ac5427", "text": "The requirement is met only for the tested straight-line dynamics envelope; the requirement or architecture needs refinement for manoeuvring."}, {"id": "163feb", "text": "Discard the manoeuvring result as an outlier."}], "answer": "ac5427"}, {"id": "m09-q12", "type": "single", "prompt": "Why is static evaluation needed alongside dynamic testing?", "explanation": "Some claims concern architecture rather than runtime response, so architecture and dependency evidence complements testing.", "options": [{"id": "77e7f9", "text": "Static evaluation is faster, so dynamic testing can be skipped."}, {"id": "af3dd7", "text": "A short dynamic test cannot prove that sources are genuinely independent; inspection and analysis can expose shared power, antenna, software, network or supplier dependencies."}, {"id": "b26f07", "text": "Static evaluation measures position error directly."}, {"id": "c69ef3", "text": "Dynamic tests cannot detect any failures."}], "answer": "af3dd7"}, {"id": "m09-q13", "type": "single", "prompt": "During a test campaign the final run passes, but an earlier run showed an unexplained mode flip. What should happen to that anomaly?", "explanation": "Do not discard inconvenient anomalies simply because the final test passed.", "options": [{"id": "27f508", "text": "Delete it, because the final result passed."}, {"id": "6c86e0", "text": "Record and investigate it: it may reveal a missing requirement, weak monitor, unmodelled dependency or incorrect assumption."}, {"id": "9fce0d", "text": "Rerun until no anomalies appear, then report only the clean run."}, {"id": "8e6aae", "text": "Report it only if the customer asks."}], "answer": "6c86e0"}, {"id": "m09-q14", "type": "multi", "prompt": "Which are recognised assurance anti-patterns?", "explanation": "Recording the configuration baseline is good practice. The others weaken objectivity, coverage or applicability.", "options": [{"id": "23edf5", "text": "Choosing pass/fail criteria after seeing the results"}, {"id": "c76bf3", "text": "Testing failover but not recovery"}, {"id": "4f10ea", "text": "Treating a simulation result as operational proof without justifying its representativeness"}, {"id": "9e836d", "text": "Treating \"certified\" as proof for every use case"}, {"id": "c9ba34", "text": "Recording the configuration baseline of the system under test"}], "answer": "23edf5,4f10ea,9e836d,c76bf3"}, {"id": "m09-q15", "type": "single", "prompt": "What is the value of a PNT assurance case?", "explanation": "An assurance case connects a top claim and sub-claims to evidence, assumptions and residual risk; it does not claim absolute resilience.", "options": [{"id": "8f277b", "text": "It turns incomplete evidence into certainty."}, {"id": "3b9b11", "text": "It makes claims, evidence, assumptions, limitations and residual risks visible and reviewable."}, {"id": "a1b74a", "text": "It replaces the need for testing."}, {"id": "ab1b67", "text": "It proves a system is resilient in all conditions."}], "answer": "3b9b11"}]}, {"moduleId": "m10", "questions": [{"id": "m10-q01", "type": "order", "prompt": "Put the first steps of the repeatable applied PNT engineering method in order.", "explanation": "Sources and mechanisms are selected because they address requirements and failure modes, not because they are fashionable.", "items": [{"id": "16a22d", "text": "Identify the PNT dependency chain"}, {"id": "4ff6cd", "text": "Design the architecture"}, {"id": "56b51a", "text": "Derive measurable requirements"}, {"id": "7bc767", "text": "Define the mission and operating context"}, {"id": "ada9ac", "text": "Define consequences of unavailable, degraded, stale or wrong PNT"}, {"id": "e1c685", "text": "Define the threat and failure model"}], "answer": "7bc767>16a22d>ada9ac>56b51a>e1c685>4ff6cd"}, {"id": "m10-q02", "type": "single", "prompt": "The coastal surveillance craft analysis shows route following, sensor geolocation and event correlation all depend on PNT. Why is \"the craft needs GPS\" an inadequate requirement?", "explanation": "A dependency analysis per mission function reveals what capability, performance and consequence each function actually has.", "options": [{"id": "6a269a", "text": "Because GPS is not available at sea."}, {"id": "f9365b", "text": "Because different mission functions consume different PNT properties and have different consequences when those properties become unreliable."}, {"id": "9f6773", "text": "Because the craft only needs timing."}, {"id": "3ff18c", "text": "Because GPS cannot be used by autonomous platforms."}], "answer": "f9365b"}, {"id": "m10-q03", "type": "match", "prompt": "Match each craft mission function to the PNT information it relies on.", "explanation": "Different functions consume different combinations of PNT, with different consequences if wrong.", "left": [{"id": "906acc", "text": "Route following"}, {"id": "0e1237", "text": "Sensor geolocation"}, {"id": "997b1a", "text": "Event correlation"}, {"id": "966015", "text": "Operator awareness"}], "right": [{"id": "6837bf", "text": "PNT state and integrity"}, {"id": "76d620", "text": "Position, time and orientation"}, {"id": "92c57f", "text": "Position, velocity and heading"}, {"id": "b62a46", "text": "Accurate time"}], "answer": "0e1237=76d620;906acc=92c57f;966015=6837bf;997b1a=b62a46"}, {"id": "m10-q04", "type": "single", "prompt": "Which requirement best passes the capstone \"requirement quality check\"?", "explanation": "A good requirement is observable, has a measurable threshold, defined conditions and duration, an identified consumer and a traceable rationale.", "options": [{"id": "60f9ec", "text": "\"The craft shall have good navigation.\""}, {"id": "ee66ee", "text": "\"A source inconsistency capable of causing more than 15 m position error shall be detected and declared within 5 s under defined test conditions.\""}, {"id": "4b6061", "text": "\"The craft shall use the best available receiver.\""}, {"id": "8956ef", "text": "\"Navigation shall be resilient to interference.\""}], "answer": "ee66ee"}, {"id": "m10-q05", "type": "single", "prompt": "The craft has two GNSS receivers sharing one antenna, one power converter and one navigation computer. How should this be assessed?", "explanation": "Whenever you see \"backup\", ask: backup against which failure? Then trace antenna, power, software, network, clock and other dependencies.", "options": [{"id": "c6298a", "text": "It is fully resilient because it has hardware redundancy."}, {"id": "9a7744", "text": "It has hardware redundancy, but a single antenna, RF, power or software fault could defeat both paths."}, {"id": "8f25fc", "text": "It is resilient because the receivers are from different vendors."}, {"id": "0cf072", "text": "It only needs a second antenna to become fully independent."}], "answer": "9a7744"}, {"id": "m10-q06", "type": "single", "prompt": "Requirement PNT-07 states that loss of the primary communications link shall not remove the craft's local navigation capability. What does it protect against?", "explanation": "Remote corrections or supervision may be lost; locally available navigation must not silently depend on that link.", "options": [{"id": "083156", "text": "GNSS spoofing."}, {"id": "fdd1ef", "text": "A hidden communications dependency that could otherwise take out navigation."}, {"id": "d2c24a", "text": "IMU bias."}, {"id": "37808b", "text": "Operator error."}], "answer": "fdd1ef"}, {"id": "m10-q07", "type": "multi", "prompt": "Why is the candidate architecture stronger than \"two GNSS receivers\"?", "explanation": "Its strength comes from complementary sources plus explicit integrity management, not source count.", "options": [{"id": "7ca35e", "text": "It separates source acquisition from trust decisions."}, {"id": "681850", "text": "It monitors health and consistency before fusion."}, {"id": "09a41f", "text": "It propagates uncertainty and integrity state to the application."}, {"id": "4f529a", "text": "It contains explicit mode-management and recovery logic."}, {"id": "1d2c1b", "text": "It uses the largest possible number of GNSS constellations."}], "answer": "09a41f,4f529a,681850,7ca35e"}, {"id": "m10-q08", "type": "truefalse", "prompt": "Redundancy without fault isolation can make deception worse.", "explanation": "A fusion algorithm that keeps weighting a plausible but corrupted source can produce a smooth, precise-looking and incorrect solution.", "options": [{"id": "true", "text": "True"}, {"id": "false", "text": "False"}], "answer": "true"}, {"id": "m10-q09", "type": "order", "prompt": "Put the stages of handling plausible-but-wrong GNSS in order.", "explanation": "A design that only detects complete signal loss can fail dangerously in this case.", "items": [{"id": "04df17", "text": "Suspect measurements are isolated from the operational solution"}, {"id": "084beb", "text": "GNSS is declared suspect"}, {"id": "88dc6e", "text": "Independent measurements begin to disagree with the GNSS solution"}, {"id": "a41de1", "text": "The integrity function evaluates residuals, dynamics and health indicators against thresholds"}, {"id": "dcfd11", "text": "The PNT manager changes mode and exposes integrity state and uncertainty"}, {"id": "f667e8", "text": "GNSS remains quarantined until revalidation criteria are met"}], "answer": "88dc6e>a41de1>084beb>04df17>dcfd11>f667e8"}, {"id": "m10-q10", "type": "match", "prompt": "Match each weak capstone approach to the better engineering response.", "explanation": "Each weak approach hides a missing trigger, bound, monitor, test or recovery criterion.", "left": [{"id": "07075e", "text": "\"If GPS fails, switch to INS.\""}, {"id": "e40845", "text": "\"Sensor fusion makes it resilient.\""}, {"id": "171b05", "text": "\"The system passed the demo.\""}, {"id": "b38861", "text": "\"GNSS has recovered, switch back.\""}], "right": [{"id": "423fba", "text": "Specify detection, failover, uncertainty growth and degraded-mode thresholds"}, {"id": "43bd40", "text": "Define health monitoring, FDI/FDE and integrity-aware fusion"}, {"id": "6bf9e8", "text": "Use traceable IADT evidence and negative and degraded testing"}, {"id": "b0d67e", "text": "Use quarantine, revalidation and controlled reintegration"}], "answer": "07075e=423fba;171b05=6bf9e8;b38861=b0d67e;e40845=43bd40"}, {"id": "m10-q11", "type": "single", "prompt": "Which verification approach fits requirement PNT-04 (\"a suspect source shall not contribute to the operational solution\")?", "explanation": "Inspection shows how exclusion is implemented; test shows the runtime behaviour when the source becomes suspect.", "options": [{"id": "14727e", "text": "Demonstration of nominal operation only."}, {"id": "b2e999", "text": "Inspection plus test: force a source into the suspect state and check fusion inputs, source state and PNT output."}, {"id": "35d3b0", "text": "Analysis of satellite geometry."}, {"id": "95e4cf", "text": "A field trial with no instrumentation."}], "answer": "b2e999"}, {"id": "m10-q12", "type": "single", "prompt": "Why is \"resilient PNT\" too broad for an assurance claim?", "explanation": "A pile of test reports is not an assurance case. Assurance explains why the evidence is sufficient for bounded claims.", "options": [{"id": "ee3eb0", "text": "Because resilience cannot be assured at all."}, {"id": "0a931a", "text": "Because a defensible claim must state the mission, environment, threat or failure conditions, performance envelope and supporting evidence."}, {"id": "669e25", "text": "Because assurance only applies to timing."}, {"id": "485d04", "text": "Because it is a trademark."}], "answer": "0a931a"}, {"id": "m10-q13", "type": "single", "prompt": "A supplier offers an emerging LEO-based source with strong headline figures but little evidence from your operating environment. What is an appropriate bounded conclusion?", "explanation": "Technology readiness is not mission readiness. Evidence of environment, integration, support, security and failure behaviour is needed.", "options": [{"id": "dfd582", "text": "Adopt it immediately as the primary source."}, {"id": "e30801", "text": "Reject it permanently because it is new."}, {"id": "79091a", "text": "Classify it as suitable now, suitable only for trial or augmentation, or insufficiently evidenced for the role, and state what evidence would change that."}, {"id": "99b821", "text": "Accept it if the supplier describes it as \"next-generation\"."}], "answer": "79091a"}, {"id": "m10-q14", "type": "single", "prompt": "A customer says \"we need resilient timing even if GPS is jammed\" for a 72-hour deployable command post. What should the engineering response begin with?", "explanation": "Do not begin by choosing a product. Requirements, threats and architecture follow from the mission and dependency analysis.", "options": [{"id": "c1309f", "text": "Choosing a rubidium clock product."}, {"id": "094309", "text": "Mission and dependency analysis: identify timing consumers, criticality, consequences and the upstream timing chain."}, {"id": "a80760", "text": "Writing the verification matrix."}, {"id": "a4314a", "text": "Adding a second GPS receiver."}], "answer": "094309"}, {"id": "m10-q15", "type": "single", "prompt": "According to the capstone assessment rubric, which areas carry the highest weighting?", "explanation": "The rubric rewards engineering traceability and judgement rather than a particular technology choice.", "options": [{"id": "7fe707", "text": "Presentation quality and diagram style"}, {"id": "47e799", "text": "Requirements engineering and architecture and rationale, at 20% each"}, {"id": "7de63f", "text": "Operational behaviour, at 40%"}, {"id": "e9caa7", "text": "Technology choice, at 50%"}], "answer": "47e799"}]}];
